package com.bananalab.lite;
import android.content.Context;import org.json.*;import java.io.*;import java.util.*;
/** Own learned retrieval of original authored lessons, not a replacement general LLM. */
final class MobileKnowledge{
 static ContextEncoder model;static JSONArray lessons;
 static synchronized void load(Context c)throws Exception{if(model!=null&&lessons!=null)return;JSONObject card=new JSONObject(read(c,"model-card.json"));if(!card.optBoolean("promoted",false))throw new IOException("Modelo local no promovido");JSONArray data=new JSONArray(read(c,"lessons.json"));String[] labels=read(c,"labels.txt").trim().split("\\n");ContextEncoder encoder=new ContextEncoder(c.getAssets().open("mobilecore1/mobilecore1.bin"),labels);lessons=data;model=encoder;}
 static String read(Context c,String file)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getAssets().open("mobilecore1/"+file)){byte[] data=new byte[4096];int n;while((n=in.read(data))!=-1){if(b.size()+n>262144)throw new IOException("Recurso demasiado grande");b.write(data,0,n);}}return b.toString("UTF-8");}
 static JSONObject find(Context c,String key)throws Exception{load(c);for(int i=0;i<lessons.length();i++){JSONObject row=lessons.getJSONObject(i);if(row.getString("key").equals(key))return row;}return null;}
 static boolean topical(JSONObject row,String message)throws Exception{String q=" "+ChatLanguage.normalize(message)+" ";JSONArray words=row.getJSONArray("keywords");for(int i=0;i<words.length();i++)if(q.contains(" "+ChatLanguage.normalize(words.getString(i))+" "))return true;JSONArray queries=row.getJSONArray("queries");for(int i=0;i<queries.length();i++)if(ChatLanguage.normalize(queries.getString(i)).equals(ChatLanguage.normalize(message)))return true;return false;}
 static String select(Context c,String message)throws Exception{String q=ChatLanguage.normalize(message);boolean asking=ResearchConversation.question(message)||q.matches("(?s)^(?:para que |quiero entender |quiero aprender |me ayudas a comprender |necesito una explicacion |podrias contarme |podes explicar |me explicas ).*");if(LocalMath.reply(message)!=null)return "";if(!asking||q.matches("(?s).*(?:hoy|actual|precio|cotizacion|presidente|mi cuenta|mi clave|mi contrasena).*" )||q.matches("(?s)^(?:busca|investiga|aprende sobre|consulta|lee|compara).*"))return "";load(c);String label=model.label(message);if(label.equals("unknown"))return "";JSONObject row=find(c,label);return row!=null&&topical(row,message)?label:"";}
 static String answer(Context c,String key,String message,String style)throws Exception{JSONObject row=find(c,key);if(row==null)return null;String q=ChatLanguage.normalize(message);String section=q.matches("(?s).*(?:ejemplo|ejemplos).*" )?"example":q.matches("(?s).*(?:paso a paso|procedimiento|como lo hago).*" )?"steps":q.startsWith("por que")||q.startsWith("porque")?"why":"explain";StringBuilder b=new StringBuilder(row.getString("title")+"\n\n"+(q.equals("otro ejemplo")?"Esta lección tiene un ejemplo preparado; todavía no genero otro distinto de forma fiable.\n":"")+row.getString(section));if(style.equals("detallado")&&section.equals("explain"))b.append("\n\nPor qué importa: ").append(row.getString("why")).append("\n\nEjemplo: ").append(row.getString("example")).append("\n\n").append(row.getString("steps"));else if(!style.equals("breve")&&section.equals("explain"))b.append("\n\nEjemplo: ").append(row.getString("example"));return b.append("\n\nGuía local de Banana; no consulté Internet.").toString();}
}
